insert into app.training_tasks(organization_id,bank,code,version,name,primary_concept,level,age_min,age_max,stages,buscamos,montaje,juega,dile,observa,easier,harder,space_note,adapta,video_guide,status,source) values
((select id from public.organizations where slug='tannery-city-fc'),'tanner','01','1.0','Balón Vivo','balon','sin_rival',null,null,array['t6','t8','t10','t12']::text[],'Dominar la pelota mientras el Tanner se mueve, frena, gira y cambia de ritmo.','Todos con balón en un espacio libre. Sin filas. Con puertas o referencias distribuidas.','Conduce libremente. El profe propone problemas: acelera, frena, gira, cambia de dirección, busca una puerta libre, usa otra superficie o la otra pierna.',array['Haz que la pelota vaya donde tú quieres.','Pelota cerca. Mira alrededor.']::text[],'Control cercano, mirada que se levanta, uso de ambas piernas, cambios de dirección y ritmo.','Amplía el espacio y reduce consignas.','Reduce espacio, agrega tráfico y señales visuales.','Completo: más desplazamientos. Reducido: más control y giros.',null,'Mostrar a todos activos y un Tanner cambiando dirección sin perder control.','oficial','Banco Tanner v1.0'),
((select id from public.organizations where slug='tannery-city-fc'),'tanner','02','1.0','Protege el Tesoro','balon','con_rival',null,null,array['t6','t8','t10','t12']::text[],'Conservar la pelota bajo presión y reconocer cuándo proteger y cuándo escapar.','Parejas en cuadrados pequeños. Un atacante con balón y un defensor.','El atacante protege la pelota. Después puede añadirse una puerta de salida: protege, encuentra el momento y escapa.',array['Tu cuerpo también protege la pelota.','Si hay salida, escapa.']::text[],'Cuerpo entre rival y balón, equilibrio, pie alejado del defensor, cambios de dirección y salida oportuna.','Defensor progresivo o más espacio.','Menos espacio, defensor activo y salida con tiempo.','Completo: cuadrado más amplio. Reducido: microduelos cortos.',null,'Captar contacto legal, protección y escape.','oficial','Banco Tanner v1.0'),
((select id from public.organizations where slug='tannery-city-fc'),'tanner','03','1.0','¿Por dónde salgo?','balon','con_decision',null,null,array['t6','t8','t10','t12']::text[],'Controlar, observar al defensor y elegir una salida.','Atacante con balón frente a defensor. Dos puertas de salida al fondo.','El atacante marca atravesando cualquiera de las dos puertas con control. El defensor decide qué camino cerrar.',array['Mira y decide.','¿Dónde está el camino?']::text[],'Lectura del defensor, engaño, primer toque útil, cambio de decisión y aceleración.','Puertas grandes y defensor más lejos.','Puertas pequeñas, tercera salida o segundo atacante.','Completo: más carrera. Reducido: decisión más rápida.',null,'Mostrar cómo una misma jugada puede resolverse por lados distintos.','oficial','Banco Tanner v1.0'),
((select id from public.organizations where slug='tannery-city-fc'),'tanner','04','1.0','Cuatro Puertas','balon','en_juego',null,null,array['t6','t8','t10','t12']::text[],'Llevar el dominio de balón a un juego real con compañeros, rivales y espacios.','2v2, 3v3 o 4v4. Cuatro puertas. Cada equipo ataca dos y defiende dos.','Se juega libre. Punto al atravesar una puerta con pelota controlada. Tras marcar, buscar otra puerta.',array['¿Dónde hay espacio?','Si hay camino, ve.']::text[],'Cabeza arriba, conducción con intención, protección, uso del compañero y cambio de orientación.','Más espacio, 3v2 o puertas grandes.','Menos espacio, puertas pequeñas o cambio de puerta objetivo.','Completo: 4v4. Reducido: 2v2/3v3.',null,'Plano abierto para ver decisiones y una acción individual que termine en puerta.','oficial','Banco Tanner v1.0'),
((select id from public.organizations where slug='tannery-city-fc'),'tanner','05','1.0','Engaña y Sal','1v1','sin_rival',null,null,array['t6','t8','t10','t12']::text[],'Aprender a engañar con cuerpo y balón antes de acelerar.','Cada Tanner con balón frente a una referencia: cono, pica o línea.','Se aproxima, realiza un engaño libre y sale con cambio de dirección y velocidad.',array['Engaña y sal.','Después del engaño, acelera.']::text[],'Cambio real de peso, balón controlado y aceleración posterior.','Sin balón primero o a baja velocidad.','Agregar señal visual que cambie la salida.','Funciona en carriles pequeños.',null,'Primer plano del engaño y salida.','oficial','Banco Tanner v1.0'),
((select id from public.organizations where slug='tannery-city-fc'),'tanner','06','1.0','Cruza la Línea','1v1','con_rival',null,null,array['t6','t8','t10','t12']::text[],'Superar a un defensor en duelo frontal.','Carril con línea de meta. Atacante con balón frente a defensor.','El atacante suma punto si cruza la línea con control. El defensor gana si recupera y sale del carril.',array['Gánale a tu rival.','Si lo pasas, acelera.']::text[],'Distancia de engaño, cambio de ritmo, protección y valentía para intentar.','Carril ancho o defensor retrasado.','Carril más estrecho o inicio más cercano.','Reducido favorece rapidez; amplio favorece carrera.',null,'Duelo completo desde inicio hasta cruce.','oficial','Banco Tanner v1.0'),
((select id from public.organizations where slug='tannery-city-fc'),'tanner','07','1.0','Dos Salidas','1v1','con_decision',null,null,array['t6','t8','t10','t12']::text[],'Leer la posición del defensor y elegir el lado con mayor ventaja.','Atacante y defensor. Dos puertas laterales o diagonales.','El atacante puede marcar por cualquiera de las dos salidas. El defensor intenta cerrar una y recuperar.',array['Mira y decide.','Haz que el rival elija primero.']::text[],'Mirada, engaño, cambio de lado y aceleración.','Puertas más amplias.','Tiempo limitado o defensor más cerca.','En espacio reducido las salidas deben quedar visibles.',null,'Mostrar lectura: defensor cierra un lado y atacante usa el otro.','oficial','Banco Tanner v1.0'),
((select id from public.organizations where slug='tannery-city-fc'),'tanner','08','1.0','Duelos que dan Gol','1v1','en_juego',null,null,array['t6','t8','t10','t12']::text[],'Reconocer cuándo el 1v1 puede crear una ocasión de gol.','2v2/3v3 con porterías. Zona o situación que provoque duelos.','Juego normal. Gol vale igual, pero se celebra el intento de superar cuando abre camino real al gol.',array['Si puedes ganarlo, atrévete.','Después del duelo, busca el gol.']::text[],'Cuándo encara y cuándo no, valentía, continuidad tras superar o perder.','Superioridad ofensiva.','Igualdad numérica y menos espacio.','Ajustar para que existan duelos reales, no embudos.',null,'Captar un 1v1 que genere tiro, pase o gol.','oficial','Banco Tanner v1.0'),
((select id from public.organizations where slug='tannery-city-fc'),'tanner','09','1.0','Pasa y Muévete','jugar_juntos','sin_rival',null,null,array['t6','t8','t10','t12']::text[],'Entender que después de pasar el Tanner vuelve a ayudar.','Triángulos o rombos con balón. Pocos jugadores por grupo.','Pasa y cambia de lugar buscando una nueva línea de pase. Evitar filas largas.',array['Pasa y vuelve a ayudar.','No te quedes mirando.']::text[],'Movimiento inmediato, orientación y nueva opción útil.','Sin oposición y espacio amplio.','Agregar defensor sombra.','Reducido exige perfiles y apoyos cortos.',null,'Mostrar pase, movimiento y segunda recepción.','oficial','Banco Tanner v1.0'),
((select id from public.organizations where slug='tannery-city-fc'),'tanner','10','1.0','2v1 Encuentra al Libre','jugar_juntos','con_rival',null,null,array['t6','t8','t10','t12']::text[],'Resolver una superioridad simple identificando al compañero libre.','2 atacantes contra 1 defensor hacia una línea o miniportería.','Los atacantes intentan superar al defensor. Pueden conducir o pasar.',array['¿Quién está libre?','Si viene contigo, alguien quedó libre.']::text[],'Fijar antes de pasar, distancia entre compañeros y momento del pase.','Defensor más lejos.','Menos espacio o segundo defensor que entra tarde.','Completo: más carrera; reducido: mayor precisión.',null,'Mostrar al defensor fijado y al compañero libre.','oficial','Banco Tanner v1.0'),
((select id from public.organizations where slug='tannery-city-fc'),'tanner','11','1.0','Tercer Hombre','jugar_juntos','con_decision',null,null,array['t6','t8','t10','t12']::text[],'Descubrir una opción que aparece después de conectar con un compañero.','3 atacantes con referencias triangulares frente a 1-2 defensores.','A juega con B y C aparece en una nueva línea. No memorizar secuencia: el objetivo es encontrar al tercer jugador disponible.',array['Uno toca. Otro aparece.','Después del pase, busca quién quedó libre.']::text[],'Movimiento sin balón, timing y lectura, no patrón mecánico.','Defensor pasivo.','Defensores activos y libertad de solución.','Reducido obliga a coordinar tiempos.',null,'Plano abierto que muestre al tercer jugador aparecer.','oficial','Banco Tanner v1.0'),
((select id from public.organizations where slug='tannery-city-fc'),'tanner','12','1.0','Gol de Todos','jugar_juntos','en_juego',null,null,array['t6','t8','t10','t12']::text[],'Crear ataques donde todos ayudan sin obligar a pasar por pasar.','3v3/4v4 con porterías.','Juego libre. Para marcar, el equipo debe haber conectado al menos con una ayuda real previa; no exigir que todos toquen el balón.',array['Ayuda al que tiene la pelota.','Dale espacio. Dale una opción.']::text[],'Espacio, apoyo, movimientos de ruptura y si el pase mejora la jugada.','Superioridad ofensiva.','Menos espacio o reinicio rápido.','Adaptable a 3v3/4v4.',null,'Gol precedido por un apoyo útil.','oficial','Banco Tanner v1.0'),
((select id from public.organizations where slug='tannery-city-fc'),'tanner','13','1.0','Mira Antes','cancha','sin_rival',null,null,array['t6','t8','t10','t12']::text[],'Crear el hábito de observar antes de recibir o conducir.','Jugadores con balón o receptores. Colores/números alrededor como información.','Antes de recibir o girar, el Tanner debe identificar una referencia que cambia.',array['Mira antes.','¿Qué hay a tu alrededor?']::text[],'Escaneo previo, orientación corporal y control hacia espacio útil.','Una sola referencia.','Varias referencias o información cambiante.','Ideal en espacios cortos con estímulos visibles.',null,'Primer plano de mirada previa y posterior recepción.','oficial','Banco Tanner v1.0'),
((select id from public.organizations where slug='tannery-city-fc'),'tanner','14','1.0','Espalda o Pies','cancha','con_rival',null,null,array['t6','t8','t10','t12']::text[],'Reconocer si conviene recibir al pie o atacar el espacio detrás.','Receptor frente a defensor y un pasador.','Según la distancia del defensor, el receptor decide venir al pie o atacar espalda.',array['¿Está lejos? Ven. ¿Está cerca? Ataca su espalda.','Mira al defensa antes de moverte.']::text[],'Lectura de distancia, momento del movimiento y orientación.','Defensor semiactivo.','Defensor libre y pase variable.','Completo permite rupturas; reducido enfatiza apoyos.',null,'Dos repeticiones contrastadas: pies y espalda.','oficial','Banco Tanner v1.0'),
((select id from public.organizations where slug='tannery-city-fc'),'tanner','15','1.0','Hombre Libre','cancha','con_decision',null,null,array['t6','t8','t10','t12']::text[],'Encontrar al jugador que tiene tiempo y espacio.','3v2 o 4v3 en zona delimitada.','El equipo conserva o progresa buscando al jugador menos presionado.',array['¿Quién tiene más tiempo?','Encuentra al libre.']::text[],'Escaneo, ocupación de espacios y velocidad para encontrar al libre.','Superioridad mayor.','Menos espacio o transición al recuperar.','Reducido exige rapidez mental.',null,'Plano abierto que muestre al libre antes del pase.','oficial','Banco Tanner v1.0'),
((select id from public.organizations where slug='tannery-city-fc'),'tanner','16','1.0','Campo de Tres Zonas','cancha','en_juego',null,null,array['t6','t8','t10','t12']::text[],'Reconocer dónde está el espacio útil sin convertir el campo en posiciones rígidas.','Juego 3v3/4v4 dividido visualmente en tres franjas.','Juego libre. Las zonas son referencia para observar ocupación, no obligación de permanecer en ellas.',array['¿Dónde hay espacio?','No te juntes por juntarte.']::text[],'Anchura, profundidad, movilidad y ocupación inteligente.','Zonas grandes.','Quitar líneas visuales tras varias repeticiones.','En cancha pequeña usar tres franjas cortas.',null,'Plano alto/abierto para ver distribución.','oficial','Banco Tanner v1.0'),
((select id from public.organizations where slug='tannery-city-fc'),'tanner','17','1.0','Atrae y Suelta','ventaja','sin_rival',null,null,array['t6','t8','t10','t12']::text[],'Entender que conducir hacia un rival puede liberar a un compañero.','Atacante con balón, compañero y defensor de referencia.','El portador avanza hasta atraer y suelta cuando el compañero queda con mejor ventaja.',array['Tráelo contigo y suelta.','Si viene contigo, alguien se libera.']::text[],'Conducir con intención y no pasar demasiado pronto.','Defensor guiado.','Defensor activo.','Necesita distancia suficiente para atraer.',null,'Mostrar al defensor desplazándose antes del pase.','oficial','Banco Tanner v1.0'),
((select id from public.organizations where slug='tannery-city-fc'),'tanner','18','1.0','2v1 Fija al Defensa','ventaja','con_rival',null,null,array['t6','t8','t10','t12']::text[],'Aprender a fijar al defensor antes de decidir pase o conducción.','2 atacantes vs 1 defensor hacia portería/línea.','Atacante con balón avanza. Si el defensor sale, pasa; si espera, puede continuar.',array['Haz que decida.','Si sale contigo, pasa. Si no, sigue.']::text[],'Distancia de fijación, tiempo del pase y ataque posterior.','Defensor retrasado.','Menos espacio o límite de tiempo.','Muy útil en carril reducido.',null,'Captar la decisión del defensor y respuesta del atacante.','oficial','Banco Tanner v1.0'),
((select id from public.organizations where slug='tannery-city-fc'),'tanner','19','1.0','3v2 ¿Dónde Sobramos?','ventaja','con_decision',null,null,array['t6','t8','t10','t12']::text[],'Reconocer dónde está la superioridad y aprovecharla.','3 atacantes contra 2 defensores.','Atacantes intentan progresar o finalizar. Los defensores pueden proteger diferentes espacios.',array['¿Dónde tenemos uno libre?','Mueve al rival y encuentra la ventaja.']::text[],'Reconocimiento del libre, amplitud y momento de acelerar.','Campo más ancho.','Tiempo corto o transición si defensores recuperan.','Reducido aumenta presión; amplio facilita lectura.',null,'Plano abierto para ver claramente 3v2.','oficial','Banco Tanner v1.0'),
((select id from public.organizations where slug='tannery-city-fc'),'tanner','20','1.0','Superioridad Viva','ventaja','en_juego',null,null,array['t6','t8','t10','t12']::text[],'Crear y aprovechar ventajas que cambian durante el juego.','3v3+1 comodín o 4v4 con comodín/intervención variable.','El equipo con balón tiene una ayuda extra. Al perderla, cambia quién dispone de superioridad.',array['Encuentra dónde somos más.','La ventaja cambia: vuelve a mirar.']::text[],'Relectura constante y adaptación tras transición.','Comodín libre.','Comodín limitado o zonas cambiantes.','Ideal en cuadrado/rectángulo adaptable.',null,'Mostrar cambio inmediato de superioridad tras pérdida.','oficial','Banco Tanner v1.0'),
((select id from public.organizations where slug='tannery-city-fc'),'tanner','21','1.0','Rompe la Línea','avanzar','sin_rival',null,null,array['t6','t8','t10','t12']::text[],'Aprender a conducir o pasar atravesando una referencia que representa oposición.','Líneas de conos o puertas que simulan líneas rivales.','El jugador busca atravesar la línea con conducción o pase hacia una nueva zona.',array['¿Puedes ir hacia adelante?','Rompe la siguiente línea.']::text[],'Orientación, intención vertical y control al cruzar.','Puertas amplias.','Agregar rival sombra.','Puede montarse en carriles.',null,'Acción clara atravesando línea con intención.','oficial','Banco Tanner v1.0'),
((select id from public.organizations where slug='tannery-city-fc'),'tanner','22','1.0','Supera al Guardián','avanzar','con_rival',null,null,array['t6','t8','t10','t12']::text[],'Decidir entre conducir, driblar o conectar para superar una oposición.','Atacante frente a un defensor que protege una zona de avance.','El atacante intenta entrar a zona siguiente. Puede añadirse compañero de apoyo.',array['Busca el camino al gol.','Si está cerrado, encuentra otro.']::text[],'Lectura, cambio de ruta y continuidad tras superar.','Defensor semiactivo.','Defensor total y zona más estrecha.','Amplio favorece conducción; reducido favorece combinación.',null,'Mostrar una solución distinta a simplemente regatear.','oficial','Banco Tanner v1.0'),
((select id from public.organizations where slug='tannery-city-fc'),'tanner','23','1.0','Dos Caminos','avanzar','con_decision',null,null,array['t6','t8','t10','t12']::text[],'Elegir entre progresar por conducción o mediante pase.','2v1/3v2 con dos corredores de avance.','El portador decide si tiene camino para conducir o si conviene conectar con compañero.',array['Si hay camino, ve. Si está cerrado, busca otro.','¿Conduces o conectas?']::text[],'No pasar por obligación ni conducir por ego; elección contextual.','Más ancho y defensor lejos.','Menos espacio y transición.','Se adapta a medio campo reducido.',null,'Dos repeticiones: una conducción y una combinación.','oficial','Banco Tanner v1.0'),
((select id from public.organizations where slug='tannery-city-fc'),'tanner','24','1.0','Gana Terreno','avanzar','en_juego',null,null,array['t6','t8','t10','t12']::text[],'Progresar colectivamente hacia portería sin perder intención.','3v3/4v4 con zonas de progresión y porterías.','Juego libre. El equipo busca superar la siguiente oposición; se puede premiar entrar controlado a zona final.',array['Busca el camino al gol.','Avanza cuando puedas.']::text[],'Verticalidad inteligente, apoyos y cambio de orientación.','Superioridad ofensiva.','Espacio reducido o reinicios rápidos.','Zonas pueden comprimirse según cancha.',null,'Ataque que supera dos líneas antes de finalizar.','oficial','Banco Tanner v1.0'),
((select id from public.organizations where slug='tannery-city-fc'),'tanner','25','1.0','Todas las Formas de Gol','gol','sin_rival',null,null,array['t6','t8','t10','t12']::text[],'Explorar distintas maneras de finalizar con precisión y decisión.','Varias estaciones de remate sin filas largas: pase, conducción corta, rebote, primera intención.','Finalizar con diferentes superficies, perfiles y ambas piernas.',array['Mira y define.','No tienes que romper la red.']::text[],'Precisión, elección de superficie y serenidad.','Balón quieto o pase suave.','Pase más vivo, perfil distinto o tiempo limitado.','Porterías adaptadas al espacio.',null,'Montaje rápido con 3 formas distintas de definir.','oficial','Banco Tanner v1.0'),
((select id from public.organizations where slug='tannery-city-fc'),'tanner','26','1.0','Ve a Buscar el Gol','gol','con_rival',null,null,array['t6','t8','t10','t12']::text[],'Atacar zonas de finalización y llegar con intención.','Centro/pase lateral con 1-2 atacantes y defensor.','Los atacantes atacan referencias: cerca, lejos o atrás. El servidor elige zona.',array['¡Ve a buscar el gol!','Cerca, lejos o atrás.']::text[],'Timing de llegada, no esperar parado, perfil y remate.','Sin defensor.','Defensor activo y servicio variable.','En cancha pequeña usar pases rasos/cutbacks.',null,'Captar movimiento previo al remate.','oficial','Banco Tanner v1.0'),
((select id from public.organizations where slug='tannery-city-fc'),'tanner','27','1.0','3v2 al Gol','gol','con_decision',null,null,array['t6','t8','t10','t12']::text[],'Resolver una ventaja ofensiva y terminar la jugada.','3 atacantes contra 2 defensores hacia portería.','Atacantes tienen pocos segundos para crear tiro claro. Si defensores recuperan, salen a zona marcada.',array['Pon la jugada a favor y termina.','Si hay tiro, no lo retrases de más.']::text[],'Último pase, fijación, aparición y decisión tiro/pase.','Más espacio.','Menos tiempo o defensor recuperador.','Funciona desde media distancia o zona corta.',null,'Secuencia completa hasta finalización.','oficial','Banco Tanner v1.0'),
((select id from public.organizations where slug='tannery-city-fc'),'tanner','28','1.0','El Gol Sigue Vivo','gol','en_juego',null,null,array['t6','t8','t10','t12']::text[],'Reaccionar a rebotes, rechaces y segundas jugadas cerca del arco.','3v3/4v4 con porterías y balones de reposición cerca del profe.','Tras tiro/rechace, la jugada continúa. No detenerse hasta que el balón salga o exista control claro.',array['¡La segunda!','El gol sigue vivo.']::text[],'Rebote, segunda acción, atacar zona de caída y concentración.','Sin transición defensiva.','Transición inmediata si rival recupera.','Ideal en área reducida.',null,'Mostrar remate, rechace y segunda acción.','oficial','Banco Tanner v1.0'),
((select id from public.organizations where slug='tannery-city-fc'),'tanner','29','1.0','Perfil y Camino','defender','sin_rival',null,null,array['t6','t8','t10','t12']::text[],'Aprender postura y orientación para llevar al atacante hacia un lado menos peligroso.','Carriles con atacante sin balón o conducción suave y defensor.','Defensor ajusta distancia y perfil sin lanzarse. Busca cerrar centro y orientar.',array['No te avientes.','Llévalo a donde tú quieres.']::text[],'Distancia, pies activos, cuerpo de lado y paciencia.','Atacante lento.','Atacante libre con balón.','Carril estrecho facilita orientación.',null,'Plano lateral mostrando perfil defensivo.','oficial','Banco Tanner v1.0'),
((select id from public.organizations where slug='tannery-city-fc'),'tanner','30','1.0','No Pasas','defender','con_rival',null,null,array['t6','t8','t10','t12']::text[],'Ganar o retrasar un duelo defensivo sin precipitarse.','1v1 en carril hacia línea o miniportería.','Atacante intenta superar; defensor protege lo peligroso y recupera cuando aparece momento.',array['Primero protege.','Acércate. Espera. Recupera.']::text[],'Temporización, pie de entrada y no regalar falta/espalda.','Atacante inicia lejos.','Más ancho o con portería real.','Reducido exige control del cuerpo.',null,'Duelo donde defensor retrasa y roba.','oficial','Banco Tanner v1.0'),
((select id from public.organizations where slug='tannery-city-fc'),'tanner','31','1.0','2v2 Salgo o Cubro','defender','con_decision',null,null,array['t6','t8','t10','t12']::text[],'Coordinar presión y cobertura entre dos defensores.','2 atacantes vs 2 defensores hacia portería/línea.','Un defensor sale al balón; el otro protege espalda y ajusta según pase.',array['Uno va. El otro cuida.','Si sale tu compañero, protégelo.']::text[],'Comunicación, distancia entre defensores y cambio de rol.','Ataque más lento.','Transición al recuperar.','Mantener anchura que permita decidir cobertura.',null,'Plano abierto para ver presión + cobertura.','oficial','Banco Tanner v1.0'),
((select id from public.organizations where slug='tannery-city-fc'),'tanner','32','1.0','Protege la Casa','defender','en_juego',null,null,array['t6','t8','t10','t12']::text[],'Defender portería y espacios peligrosos como equipo.','3v3/4v4 con portería y zona central peligrosa marcada de forma visual.','Juego normal. Defensores priorizan proteger centro, área y portería; al recuperar, juegan.',array['Primero protege lo peligroso.','Uno va. Todos defienden.']::text[],'Centro protegido, ayudas, coberturas y salida tras robo.','Zona central más clara.','Quitar referencias y jugar libre.','Adaptable a cancha completa/reducida.',null,'Secuencia de ayuda colectiva y recuperación.','oficial','Banco Tanner v1.0'),
((select id from public.organizations where slug='tannery-city-fc'),'tanner','33','1.0','Cambia el Chip','reaccionar','sin_rival',null,null,array['t6','t8','t10','t12']::text[],'Crear hábito de cambiar inmediatamente de rol cuando cambia la posesión.','Parejas/grupos con señales de cambio entre ataque y defensa.','Ante una señal o pérdida simulada, quien atacaba defiende y quien defendía ataca.',array['Siguiente jugada.','Cambió el balón: cambia tú.']::text[],'Velocidad mental, primer movimiento y actitud.','Señal clara y pausada.','Cambio inesperado dentro de tarea con balón.','Muy adaptable.',null,'Cambio instantáneo de dirección/rol.','oficial','Banco Tanner v1.0'),
((select id from public.organizations where slug='tannery-city-fc'),'tanner','34','1.0','Perdí, Recupero','reaccionar','con_rival',null,null,array['t6','t8','t10','t12']::text[],'Intentar recuperar inmediatamente cuando existe una oportunidad real.','1v1/2v2. Tras pérdida, poseedor tiene oportunidad breve de recuperar.','Si pierdes, reaccionas. Si recuperar ya no es posible, vuelves a proteger.',array['Si puedes recuperar, ve.','Si no, protege.']::text[],'Primeros pasos tras pérdida y capacidad de abandonar presión inútil.','Espacio reducido.','Más jugadores y salida del rival.','Reducido favorece contrapresión; amplio exige reconocer cuándo parar.',null,'Pérdida, reacción y decisión recuperar/proteger.','oficial','Banco Tanner v1.0'),
((select id from public.organizations where slug='tannery-city-fc'),'tanner','35','1.0','¿Ataco o Aseguro?','reaccionar','con_decision',null,null,array['t6','t8','t10','t12']::text[],'Leer qué hacer inmediatamente después de recuperar el balón.','2v2/3v3 con miniporterías o zonas de salida.','Al recuperar, el equipo decide: si existe ventaja, ataca; si no, asegura y construye.',array['¿Hay camino? Vamos.','¿No hay? Calma y construye.']::text[],'Ritmo, primer pase/conducción, mirada y no confundir rapidez con prisa.','Dar superioridad al equipo que recupera.','Tiempo y espacio menores.','Funciona especialmente bien en espacio medio.',null,'Dos ejemplos: transición rápida y pausa inteligente.','oficial','Banco Tanner v1.0'),
((select id from public.organizations where slug='tannery-city-fc'),'tanner','36','1.0','Partido sin Pausa','reaccionar','en_juego',null,null,array['t6','t8','t10','t12']::text[],'Integrar transiciones, ritmo, reinicios rápidos y segunda jugada dentro del partido.','3v3/4v4/5v5. Balones disponibles alrededor para reiniciar rápido.','Partido continuo. Cuando balón sale, reinicio inmediato cuando las reglas lo permiten. Se premia estar listo antes que el rival.',array['¿Podemos jugar ya?','¡La segunda!','Reacciona y sigue jugando.']::text[],'Atención, velocidad de reinicio, segunda jugada, ritmo y reorganización.','Reinicios guiados por profe.','Jugadores gestionan los reinicios por sí mismos.','Cualquier formato de juego reducido.',null,'Secuencia de salida, reinicio rápido y transición posterior.','oficial','Banco Tanner v1.0'),
((select id from public.organizations where slug='tannery-city-fc'),'baby','B01','1.0','Semáforo Tanner','movimiento',null,3,6,array['baby_3_4','baby_5_6']::text[],'Moverse, frenar y arrancar con control del cuerpo.','Todos libres en un espacio seguro. Sin balón al inicio; después puede entrar balón.','Verde: avanza. Amarillo: lento. Rojo: frena y queda estable. Cambiar direcciones y formas de desplazarse.',array['Verde: voy. Rojo: freno.']::text[],'Frena sin caerse, vuelve a arrancar, escucha una señal simple.','Menos señales y más espacio.','Agregar balón o señales visuales.',null,'3-4: caminar/correr. 5-6: cambios de dirección y balón.','Mostrar reacción a señal, frenado y nueva salida.','oficial','Banco Baby Tanners v1.0'),
((select id from public.organizations where slug='tannery-city-fc'),'baby','B02','1.0','Islas Tanner','movimiento',null,3,6,array['baby_3_4','baby_5_6']::text[],'Explorar espacio, orientación y cambios de dirección.','Aros o cuadrados como islas distribuidas.','Los niños se mueven por el mar y, a una señal, encuentran una isla libre sin chocar.',array['Busca una isla libre.']::text[],'Mira alrededor, evita choques, cambia camino.','Más islas y espacio.','Menos islas o entrar con balón.',null,'3-4: llegar a cualquier isla. 5-6: color/forma indicada.','Plano abierto mostrando búsqueda de espacio.','oficial','Banco Baby Tanners v1.0'),
((select id from public.organizations where slug='tannery-city-fc'),'baby','B03','1.0','Frena y Sal','movimiento',null,4,6,array['baby_3_4','baby_5_6']::text[],'Aprender a desacelerar y volver a arrancar.','Carriles muy cortos con una referencia de frenado.','Corre hasta la referencia, frena controlado y sale hacia otro lado.',array['Frena fuerte. Cambia. Sal.']::text[],'Pasos cortos al frenar, equilibrio y nueva aceleración.','Menor velocidad.','Señal de salida aleatoria o balón.',null,'3-4: versión caminando/corriendo suave. 5-6: más velocidad.','Toma lateral de frenado y cambio.','oficial','Banco Baby Tanners v1.0'),
((select id from public.organizations where slug='tannery-city-fc'),'baby','B04','1.0','Salta y Aterriza','movimiento',null,3,6,array['baby_3_4','baby_5_6']::text[],'Saltar y caer de forma estable y segura.','Líneas, aros o pequeñas marcas en el piso.','Saltar dentro/fuera, adelante/lado y caer con control.',array['Salta. Cae suave.']::text[],'Rodillas flexionadas, equilibrio y seguridad.','Saltos pequeños con dos pies.','Direcciones variadas o recibir balón después.',null,'No usar alturas grandes.','Primer plano de aterrizaje estable.','oficial','Banco Baby Tanners v1.0'),
((select id from public.organizations where slug='tannery-city-fc'),'baby','B05','1.0','Caigo y Sigo','movimiento',null,4,6,array['baby_3_4','baby_5_6']::text[],'Perder el miedo a caer y volver a participar.','Zona segura, césped y tareas simples de caída controlada.','Desde posiciones bajas, practicar caer, levantarse y volver a una acción sencilla.',array['Caes. Te levantas. Sigues.']::text[],'Apoyo de manos seguro, levantarse sin drama, volver al juego.','Desde sentado/rodillas.','Después de levantarse, correr por balón.',null,'Siempre progresivo y supervisado.','Mostrar caída controlada, levantarse y seguir.','oficial','Banco Baby Tanners v1.0'),
((select id from public.organizations where slug='tannery-city-fc'),'baby','B06','1.0','Persigue la Sombra','movimiento',null,3,6,array['baby_3_4','baby_5_6']::text[],'Coordinar el cuerpo siguiendo cambios de dirección de otro niño.','Parejas con espacio suficiente.','Uno guía y el otro sigue como sombra. Cambian cada 20-30 s.',array['Síguelo sin chocarlo.']::text[],'Atención, coordinación, respeto de espacio.','Profesor guía al grupo.','Con balón para el guía 5-6.',null,'3-4: movimientos simples. 5-6: cambios de ritmo.','Pareja moviéndose con diversión y control.','oficial','Banco Baby Tanners v1.0'),
((select id from public.organizations where slug='tannery-city-fc'),'baby','B07','1.0','Pelota Viajera','balon',null,3,6,array['baby_3_4','baby_5_6']::text[],'Disfrutar mover la pelota en distintas direcciones.','Cada niño con balón. Espacio amplio y seguro.','Empuja la pelota, síguela, deténla, llévala a otro lugar.',array['Haz que tu pelota viaje.']::text[],'Contacto frecuente, curiosidad y control progresivo.','Sin consignas técnicas.','Agregar puertas/colores.',null,'3-4: libertad. 5-6: cambios de pie y dirección.','Mostrar muchos niños con balón y sin filas.','oficial','Banco Baby Tanners v1.0'),
((select id from public.organizations where slug='tannery-city-fc'),'baby','B08','1.0','El Balón me Sigue','balon',null,3,6,array['baby_3_4','baby_5_6']::text[],'Mantener la pelota cerca mientras se desplaza.','Todos con balón en un espacio marcado.','Conducir sin que la pelota se aleje demasiado; parar cuando el profe cambia la señal.',array['Que no se te escape.']::text[],'Toques adecuados, mirada ocasional arriba, frenado.','Más espacio y ritmo lento.','Menos espacio o tráfico.',null,'5-6 puede usar ambas piernas de forma natural.','Detalle de control cercano.','oficial','Banco Baby Tanners v1.0'),
((select id from public.organizations where slug='tannery-city-fc'),'baby','B09','1.0','Casas de Color','balon',null,3,6,array['baby_3_4','baby_5_6']::text[],'Conducir hacia un objetivo visible y reconocer espacio.','Puertas/casas de colores alrededor.','El profe nombra o muestra un color; cada niño lleva su balón a una casa de ese color.',array['Lleva tu pelota a una casa.']::text[],'Conducción con intención y elección de ruta.','Una sola casa grande.','Varias casas del mismo color para elegir.',null,'3-4: color simple. 5-6: color cambia durante recorrido.','Plano abierto con rutas diferentes.','oficial','Banco Baby Tanners v1.0'),
((select id from public.organizations where slug='tannery-city-fc'),'baby','B10','1.0','Gira y Escapa','balon',null,4,6,array['baby_3_4','baby_5_6']::text[],'Descubrir giros sencillos con balón.','Cada niño con balón y una línea/referencia.','Llegar a la referencia, girar como quiera y salir a otro lado.',array['Gira y vete.']::text[],'Mantiene balón cerca y acelera tras girar.','Giro libre sin velocidad.','Señal visual que indique salida.',null,'No exigir gesto técnico único.','Mostrar 2-3 soluciones distintas.','oficial','Banco Baby Tanners v1.0'),
((select id from public.organizations where slug='tannery-city-fc'),'baby','B11','1.0','Protege tu Pelota','balon',null,4,6,array['baby_3_4','baby_5_6']::text[],'Empezar a usar cuerpo y balón frente a oposición suave.','Parejas. Un niño con balón, otro intenta tocarlo con pie de forma controlada.','El poseedor mantiene la pelota y cambia de dirección; rotaciones muy cortas.',array['Cuida tu pelota.']::text[],'Cuerpo entre rival y balón, equilibrio y juego seguro.','Defensor solo acompaña.','Defensor intenta recuperar.',null,'Contacto ligero, sin empujar.','Captar protección y sonrisa/juego.','oficial','Banco Baby Tanners v1.0'),
((select id from public.organizations where slug='tannery-city-fc'),'baby','B12','1.0','Empuja al Gol','balon',null,3,6,array['baby_3_4','baby_5_6']::text[],'Relacionar conducción con el objetivo de hacer gol.','Miniporterías distribuidas. Cada niño con balón o grupos muy pequeños.','Conducir hacia una portería y empujar/rematar para marcar. Buscar otra portería después.',array['Lleva la pelota al gol.']::text[],'Intención, control y alegría al finalizar.','Porterías grandes y cercanas.','Elegir entre dos porterías o defensor sombra.',null,'5-6 puede mirar portería antes de tirar.','Conducción + gol + búsqueda de nueva meta.','oficial','Banco Baby Tanners v1.0'),
((select id from public.organizations where slug='tannery-city-fc'),'baby','B13','1.0','Encuentra la Portería','juego',null,3,6,array['baby_3_4','baby_5_6']::text[],'Reconocer hacia dónde atacar.','2v2/3v3 con dos porterías claras.','Partido simple. El profe solo recuerda cuál es la portería que atacan.',array['¿Dónde está tu gol?']::text[],'Orientación, participación y búsqueda de portería.','1v1/2v2.','3v3 con reinicios rápidos.',null,'Muy pocas reglas.','Plano abierto mostrando orientación hacia meta.','oficial','Banco Baby Tanners v1.0'),
((select id from public.organizations where slug='tannery-city-fc'),'baby','B14','1.0','Roba y Marca','juego',null,4,6,array['baby_3_4','baby_5_6']::text[],'Descubrir que sin balón podemos recuperarlo y después atacar.','1v1 o 2v2 hacia miniporterías.','Si recuperas, inmediatamente puedes ir a marcar.',array['Recupera y ve al gol.']::text[],'Cambio ataque-defensa, valentía y continuidad.','1v1 con mucho espacio.','2v2 y transición libre.',null,'Sin explicaciones tácticas.','Robo sencillo seguido de ataque.','oficial','Banco Baby Tanners v1.0'),
((select id from public.organizations where slug='tannery-city-fc'),'baby','B15','1.0','Dos Caminos','juego',null,4,6,array['baby_3_4','baby_5_6']::text[],'Elegir entre dos rutas hacia el gol.','Dos puertas/porterías pequeñas disponibles para atacar.','El niño con balón elige una de dos salidas o metas.',array['¿Por dónde quieres ir?']::text[],'Mirada, decisión simple, cambio de ruta.','Puertas grandes sin rival.','Agregar defensor suave.',null,'3-4 puede hacerse sin rival.','Mostrar elección diferente entre repeticiones.','oficial','Banco Baby Tanners v1.0'),
((select id from public.organizations where slug='tannery-city-fc'),'baby','B16','1.0','Puertas Mágicas','juego',null,3,6,array['baby_3_4','baby_5_6']::text[],'Jugar con balón buscando espacios.','Varias puertas de conos dentro del campo.','1v1/2v2/3v3. Punto al cruzar una puerta con balón controlado.',array['Busca una puerta libre.']::text[],'Exploración, conducción y no amontonarse.','Más puertas.','Menos puertas o rival activo.',null,'En 3-4 usar sin marcador si hace falta.','Plano abierto para ver puertas libres.','oficial','Banco Baby Tanners v1.0'),
((select id from public.organizations where slug='tannery-city-fc'),'baby','B17','1.0','Gol y Vuelve','juego',null,3,6,array['baby_3_4','baby_5_6']::text[],'Aprender a reengancharse después de marcar o perder una jugada.','Partido pequeño con balones de reposición.','Después de gol o balón fuera, el juego vuelve a empezar rápido.',array['Gol. Vuelve a jugar.']::text[],'No quedarse celebrando/desconectado, volver al juego con alegría.','Reinicios guiados.','Niños ayudan a reiniciar.',null,'Celebrar sí; desconectarse no.','Gol, celebración breve y regreso.','oficial','Banco Baby Tanners v1.0'),
((select id from public.organizations where slug='tannery-city-fc'),'baby','B18','1.0','Partidito Vivo','juego',null,3,6,array['baby_3_4','baby_5_6']::text[],'Vivir fútbol libre con la menor intervención posible.','1v1, 2v2 o 3v3; porterías adaptadas.','Jugar. El profe interviene poco y observa. Reinicios simples y rápidos.',array['Juega. Inténtalo. Otra vez.']::text[],'Participación, alegría, balón, orientación básica y convivencia.','Menos jugadores y espacio amplio.','3v3, más continuidad y decisiones.',null,'Debe aparecer prácticamente todas las sesiones cuando sea posible.','Video emocional: juego real, niños resolviendo solos.','oficial','Banco Baby Tanners v1.0'),
((select id from public.organizations where slug='tannery-city-fc'),'baby','B19','1.0','Saludo Tanner','convivencia',null,3,6,array['baby_3_4','baby_5_6']::text[],'Crear seguridad, pertenencia y hábito de reconocer a los demás.','Ritual corto de llegada o inicio.','Cada niño saluda al profe y a uno o dos compañeros; puede incluir nombre y choque de manos.',array['Hola, soy Tanner.']::text[],'Contacto respetuoso, decir nombre, mirar y participar.','Solo saludo al profe.','Niño presenta a compañero.',null,'Debe durar pocos minutos.','Mostrar ritual natural, no actuación rígida.','oficial','Banco Baby Tanners v1.0'),
((select id from public.organizations where slug='tannery-city-fc'),'baby','B20','1.0','Mi Turno, Tu Turno','convivencia',null,3,6,array['baby_3_4','baby_5_6']::text[],'Aprender a esperar brevemente y respetar turnos sin crear filas largas.','Parejas o tríos con un balón/tarea corta.','Uno realiza acción corta, entrega/cede el balón al siguiente y vuelve a participar rápido.',array['Ahora tú. Después yo.']::text[],'Respeto, transición rápida y paciencia breve.','Parejas.','Tríos y elección de siguiente compañero.',null,'No convertirlo en espera prolongada.','Mostrar cambio fluido de turno.','oficial','Banco Baby Tanners v1.0'),
((select id from public.organizations where slug='tannery-city-fc'),'baby','B21','1.0','Te Ayudo','convivencia',null,3,6,array['baby_3_4','baby_5_6']::text[],'Descubrir que un compañero también puede ayudar.','Parejas con misión sencilla: transportar balones, pasar por puertas, recoger material.','Resolver juntos una tarea simple con pelota o material.',array['Hazlo con tu compañero.']::text[],'Cooperación, comunicación simple, no arrebatar.','Tarea muy simple y corta.','Agregar decisión de cómo resolver.',null,'No buscar táctica; buscar convivencia.','Pareja resolviendo junta.','oficial','Banco Baby Tanners v1.0'),
((select id from public.organizations where slug='tannery-city-fc'),'baby','B22','1.0','Cuido mi Balón','convivencia',null,3,6,array['baby_3_4','baby_5_6']::text[],'Crear responsabilidad por material y pertenencias.','Cada niño identifica su balón/material al inicio o cierre.','Al terminar una parte, lleva su balón al lugar indicado y vuelve al grupo.',array['Cuida lo que usamos.']::text[],'Orden, cuidado, autonomía progresiva.','Profesor acompaña físicamente.','Niños ayudan a organizar estación.',null,'Convertir en rutina, no castigo.','Mostrar al niño guardando material con orgullo.','oficial','Banco Baby Tanners v1.0'),
((select id from public.organizations where slug='tannery-city-fc'),'baby','B23','1.0','Celebramos Juntos','convivencia',null,3,6,array['baby_3_4','baby_5_6']::text[],'Aprender a celebrar sin burlarse ni excluir.','Integrado a partiditos o finalizaciones.','Después de gol/éxito, celebración corta con compañeros y volver a jugar.',array['El gol lo celebra el equipo.']::text[],'Alegría, inclusión, respeto al rival.','Celebración guiada.','Niños crean celebración breve del equipo.',null,'Nunca humillar o festejar frente a la cara del rival.','Captar celebración colectiva positiva.','oficial','Banco Baby Tanners v1.0'),
((select id from public.organizations where slug='tannery-city-fc'),'baby','B24','1.0','Ordenamos Juntos','convivencia',null,3,6,array['baby_3_4','baby_5_6']::text[],'Cerrar con responsabilidad y sentido de equipo.','Material disperso de forma segura al terminar.','Todos ayudan 1-2 minutos a juntar balones/conos y dejar el espacio listo.',array['Todos ayudamos.']::text[],'Participación, cuidado y cierre tranquilo.','Cada uno recoge una cosa.','Pequeños equipos por tipo de material.',null,'No usar como castigo.','Mostrar cierre colectivo y saludo final.','oficial','Banco Baby Tanners v1.0')
